// Generates the SDK's design-system modules from the vendored design-system/
// folder (the only source of visual truth), so a token-only design-system PR
// changes rendering after `npm run build` with no code edits.
//
//   node scripts/gen-design-system.mjs          write generated files
//   node scripts/gen-design-system.mjs --check  fail if generated files are stale
//
// Writes:
//   sdk/core/src/generated/designSystem.ts   tokens (all 8 themes), metrics, fonts, type styles
//   sdk/core/src/generated/geometry/*.ts     blob.ts + blobShapes.ts, verbatim copies
//   sdk/react/src/generated/specCss.ts       tokens.css + spec.css as strings (injected at runtime)
//   sdk/{core,react}/design-system/          LICENSE + NOTICE.md (shipped with the packages)
//   sdk/react/fonts/Caveat-Variable.ttf      bundled font file (shipped with the package)

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const ds = resolve(root, 'design-system');
const core = resolve(root, 'renderers/visualli-sdk/sdk/core');
const react = resolve(root, 'renderers/visualli-sdk/sdk/react');
const check = process.argv.includes('--check');

const HEADER = (src) => `// GENERATED by scripts/gen-design-system.mjs from design-system/ (${src}). Do not edit.\n// Change the design system instead; the next \`npm run build\` regenerates this file.\n`;

let stale = [];
function out(path, content) {
  if (check) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) stale.push(path.replace(root + '/', ''));
    return;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
}
function copy(src, dst) {
  const content = readFileSync(src);
  if (check) {
    if (!existsSync(dst) || !readFileSync(dst).equals(content)) stale.push(dst.replace(root + '/', ''));
    return;
  }
  mkdirSync(dirname(dst), { recursive: true });
  copyFileSync(src, dst);
}

// ── tokens ───────────────────────────────────────────────────────────────────
const tokensJson = JSON.parse(readFileSync(resolve(ds, 'tokens/tokens.json'), 'utf8'));
const manifest = JSON.parse(readFileSync(resolve(ds, 'manifest.json'), 'utf8'));
const THEME_NAMES = ['light', 'dark', 'focus-light', 'focus-dark', 'colorsafe-light', 'colorsafe-dark', 'contrast-light', 'contrast-dark'];
for (const t of THEME_NAMES) if (!tokensJson.themes[t]) throw new Error(`tokens.json is missing theme "${t}"`);

// Each theme is a sparse override of "light" (that is how tokens.css applies them).
const base = tokensJson.themes.light;
const tokens = Object.fromEntries(THEME_NAMES.map((t) => [t, { ...base, ...tokensJson.themes[t] }]));
const motionReduced = tokensJson.themes['data-motion=reduced'] ?? {};

const camel = (k) => k.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const num = (v) => (/^-?\d+(\.\d+)?(px|ms)?$/.test(v) ? parseFloat(v) : null);
const metrics = {};
for (const [k, v] of Object.entries(base)) { const n = num(v); if (n !== null) metrics[camel(k)] = n; }
const metricsReduced = {};
for (const [k, v] of Object.entries(motionReduced)) { const n = num(v); if (n !== null) metricsReduced[camel(k)] = n; }

const topics = [...new Set(Object.keys(base).filter((k) => /^topic-[a-z]+$/.test(k)).map((k) => k.slice(6)))];

// Canvas type styles live in tokens.css under "/* Type styles */".
const css = readFileSync(resolve(ds, 'tokens/tokens.css'), 'utf8');
const typeStyles = {};
for (const m of css.slice(css.indexOf('/* Type styles */')).matchAll(/\.([a-z-]+)\s*\{([^}]*)\}/g)) {
  const body = m[2];
  const family = /font-family:\s*var\(--([a-z-]+)\)/.exec(body)?.[1];
  const size = /font-size:\s*([\d.]+)px/.exec(body)?.[1];
  const lh = /line-height:\s*([\d.]+)px/.exec(body)?.[1];
  const weight = /font-weight:\s*(\d+)/.exec(body)?.[1];
  const ls = /letter-spacing:\s*([\d.]+)em/.exec(body)?.[1];
  if (family && size) typeStyles[m[1]] = { family, size: +size, lineHeight: +lh, weight: +weight, ...(ls ? { letterSpacing: +ls } : {}) };
}

// Canvas styling that lives in css/spec.css (DOM components) and must also be
// honoured by the canvas renderer. Extracted by regex; a missing rule fails the
// build loudly so a design-system change never silently drops out of the canvas.
const specRaw = readFileSync(resolve(ds, 'css/spec.css'), 'utf8');
const pick = (re, what) => {
  const m = re.exec(specRaw);
  if (!m) throw new Error(`design-system/css/spec.css: could not find ${what}`);
  return m;
};
const numList = (v) => v.trim().split(/\s+/).map(Number);
const edgeFont = pick(/\.vi-edge__label \{ font: (\d+) calc\((\d+)px/, '.vi-edge__label font');
const groupFont = pick(/\.vi-map__group text \{ font: (\d+) (\d+)px/, '.vi-map__group text font');
const readableEdge = pick(/\[data-type="readable"\] \.vi-edge__label \{ font-size: calc\((\d+)px[^}]*font-weight: (\d+)/, 'readable edge label');
const hover = pick(/button\.vi-node:hover \.vi-node__rings \{ transform: rotate\((-?[\d.]+)deg\) scale\(([\d.]+)\)/, 'node hover rings transform');
const lift = pick(/button\.vi-node:hover \{ transform: translateY\((-?[\d.]+)px\)/, 'node hover lift');
const canvasStyle = {
  node: {
    labelLineHeight: +pick(/\.vi-node__label \{[^}]*line-height: ([\d.]+)/, '.vi-node__label line-height')[1],
    labelMaxLines: +pick(/\.vi-node__label \{[^}]*-webkit-line-clamp: (\d+)/, '.vi-node__label line clamp')[1],
    selectedStrokeWidth: +pick(/\.vi-node\.is-selected \.vi-node__body \{ stroke-width: ([\d.]+)/, 'selected node stroke')[1],
    hoverRingsRotate: +hover[1],
    hoverRingsScale: +hover[2],
    hoverLift: +lift[1],
    dimmedOpacityFocus: +pick(/\[data-theme\^="focus"\] \.vi-node\.is-dimmed \{ opacity: ([\d.]+)/, 'focus dimmed opacity')[1],
    dimmedOpacityHighlight: +pick(/\.vi-map\.has-highlight \.vi-node\.is-dimmed \{ opacity: ([\d.]+)/, 'highlight dimmed opacity')[1],
    shadowLight: pick(/--vi-node-shadow, ([^)]+\))\)/, 'light node shadow')[1],
    shadowDark: pick(/\[data-theme\$="dark"\] \.vi-node__body \{ --vi-node-shadow: ([^;]+);/, 'dark node shadow')[1],
  },
  edge: {
    dash: numList(pick(/\.vi-edge\.is-dashed \.vi-edge__line \{ stroke-dasharray: ([\d ]+);/, 'dashed edge')[1]),
    labelWeight: +edgeFont[1],
    labelSize: +edgeFont[2],
    readableLabelSize: +readableEdge[1],
    readableLabelWeight: +readableEdge[2],
    labelHaloWidth: +pick(/\.vi-edge__label \{[^}]*stroke-width: ([\d.]+)px/, 'edge label halo')[1],
    selectedStrokeWidth: +pick(/\.vi-edge\.is-selected \.vi-edge__line[^{]*\{[^}]*stroke-width: ([\d.]+)/, 'selected edge stroke')[1],
  },
  group: {
    strokeWidth: +pick(/\.vi-map__group rect \{[^}]*stroke-width: ([\d.]+)/, 'group stroke width')[1],
    dash: numList(pick(/\.vi-map__group rect \{[^}]*stroke-dasharray: ([\d ]+);/, 'group dash')[1]),
    labelWeight: +groupFont[1],
    labelSize: +groupFont[2],
  },
};

const j = (o) => JSON.stringify(o, null, 2);
out(resolve(core, 'src/generated/designSystem.ts'), `${HEADER('tokens/tokens.json, tokens/tokens.css')}
/** Version of the design system these modules were generated from. */
export const DESIGN_SYSTEM_VERSION = ${j(tokensJson.version)} as const;

export const THEME_NAMES = ${j(THEME_NAMES)} as const;
export type ThemeName = (typeof THEME_NAMES)[number];

/** Every token for every theme (each theme already merged over "light"). Keys match the CSS custom properties. */
export const TOKENS: Readonly<Record<ThemeName, Readonly<Record<string, string>>>> = ${j(tokens)};

/** Topic palette names (token pairs \`topic-<name>\` / \`topic-<name>-ring\`). */
export const TOPICS = ${j(topics)} as const;
export type TopicName = (typeof TOPICS)[number];

/** Numeric tokens (px / ms stripped), camel-cased: nodeWidth, nodeStroke, edgeWidth, edgeGap, durationBase, zoomMin ... */
export const METRICS = ${j(metrics)} as const;
/** Overrides applied when motion is reduced. */
export const METRICS_REDUCED_MOTION = ${j(metricsReduced)} as const;

/** Canvas type styles (family is a token name: font-hand, font-note, font-ui ...). */
export const TYPE_STYLES = ${j(typeStyles)} as const;

/** Canvas styling extracted from css/spec.css (node labels, hover, shadows, connector dashes, group frames). */
export const CANVAS_STYLE = ${j(canvasStyle)} as const;
`);

// ── geometry (verbatim) ──────────────────────────────────────────────────────
copy(resolve(ds, 'geometry/blob.ts'), resolve(core, 'src/generated/geometry/blob.ts'));
copy(resolve(ds, 'geometry/blobShapes.ts'), resolve(core, 'src/generated/geometry/blobShapes.ts'));

// ── spec CSS for the DOM overlays ────────────────────────────────────────────
// The page must keep its own <body> styles, so the spec's global `body{}` rule
// is dropped; `@import` lines are dropped too (fonts are loaded by the SDK).
const specCss = readFileSync(resolve(ds, 'css/spec.css'), 'utf8').replace(/^body\s*\{[^}]*\}\s*$/m, '').replace(/^@import[^\n]*\n/gm, '');
const tokensCss = css.replace(/^@import[^\n]*\n/gm, '');
// Bundled font files declared in fonts/fonts.css (@font-face with a local url()).
const fontsCss = readFileSync(resolve(ds, 'fonts/fonts.css'), 'utf8');
const bundledFonts = [...fontsCss.matchAll(/@font-face\s*\{([^}]*)\}/g)].flatMap((m) => {
  const family = /font-family:\s*"([^"]+)"/.exec(m[1])?.[1];
  const file = /src:\s*url\("\.\/([^"]+)"\)/.exec(m[1])?.[1];
  const weight = /font-weight:\s*([\d ]+);/.exec(m[1])?.[1]?.trim();
  return family && file ? [{ family, file, weight: weight ?? '400' }] : [];
});
if (!bundledFonts.length) throw new Error('design-system/fonts/fonts.css: no bundled @font-face found');

out(resolve(react, 'src/generated/specCss.ts'), `${HEADER('tokens/tokens.css, css/spec.css')}
export const SPEC_TOKENS_CSS = ${JSON.stringify(tokensCss)};
export const SPEC_COMPONENT_CSS = ${JSON.stringify(specCss)};
export const SPEC_FONTS_URL = ${JSON.stringify(/@import url\("([^"]+)"\)/.exec(readFileSync(resolve(ds, 'fonts/fonts.css'), 'utf8'))?.[1] ?? '')};
export const SPEC_DESIGN_SYSTEM_VERSION = ${j(manifest.version)};
/** Font files shipped with the package (fonts/ directory), from design-system/fonts/fonts.css. */
export const SPEC_BUNDLED_FONTS = ${j(bundledFonts)} as const;
`);

// ── licences + bundled font ship with the packages ───────────────────────────
for (const pkg of [core, react]) {
  copy(resolve(ds, 'LICENSE'), resolve(pkg, 'design-system/LICENSE'));
  copy(resolve(ds, 'NOTICE.md'), resolve(pkg, 'design-system/NOTICE.md'));
}
copy(resolve(ds, 'fonts/Caveat-Variable.ttf'), resolve(react, 'fonts/Caveat-Variable.ttf'));
// The playground / benchmark app serves the same file locally.
copy(resolve(ds, 'fonts/Caveat-Variable.ttf'), resolve(root, 'renderers/visualli-sdk/apps/react/public/fonts/Caveat-Variable.ttf'));

if (check) {
  if (stale.length) { console.error(`Generated design-system files are stale:\n  ${stale.join('\n  ')}\nRun: node scripts/gen-design-system.mjs`); process.exit(1); }
  console.log('design-system generated files are up to date');
}
